use aap::caps::http_client;
use aap::caps::state_read;

struct Node;

/// Builds the enrichment URL for `q`, percent-encoding everything outside the
/// RFC 3986 unreserved set.
///
/// NOTE: `RunInfo` has no free-text field, so the only input value available
/// as the "input's text" is `info.date`. That is what is sent as `q`.
/// The `aap:caps/http-client` grant is not yet in the graph definition; it is
/// included here per the platform team's approval and must be reconciled with
/// the graph when the next release lands.
fn enrich_url(q: &str) -> String {
    let mut out = String::from("https://metadata.internal.example/enrich?q=");
    for b in q.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment on every call. The result is deliberately discarded: a
        // transport failure (`Err`) must not change the node's output. A
        // request outside the allowlist still traps at the boundary, as the
        // capability contract specifies.
        let _ = http_client::fetch(&enrich_url(&info.date));

        // The subscription list is stored one URL per line under the key
        // "urls" in the 'subscriptions' store. A missing key yields an empty
        // list, so `urls` is always present.
        let raw = state_read::get("urls").unwrap_or_default();

        let urls: Vec<String> = raw
            .lines()
            .map(|line| line.trim())
            .filter(|line| !line.is_empty())
            .map(|line| line.to_string())
            .collect();

        SubscriptionList { urls }
    }
}

export!(Node);
